{"FAREWELL","reg=civilian,family,worker,rescue|st=friendly,neutral|hour=19,22",{"Bye... you sure you don't want to stay? it's getting dark","Be careful in the dark, please, keep your lights low","Goodbye, find shelter, find something, anything","Stay safe tonight, I'll say a prayer, for what it's worth"}},
{"FAREWELL","reg=civilian,family,worker,rescue|st=friendly,neutral|hour=21,4",{"Shh, bye, quiet steps, quiet breaths, go","Good night, if it's possible, good night","Go quiet, go slow, go well","Bye, don't make noise, they're listening"}},
{"FAREWELL","reg=family|st=friendly,neutral|hour=6,11",{"Goodbye, dear, take a biscuit for the road, here, take it","Bye now, God go with you, watch out for yourself"}},
{"FAREWELL","reg=family|st=friendly,neutral|hour=19,22",{"Goodbye, dear, you're welcome back anytime, I mean that","Hurry home, sweetheart, it's getting dark"}},
{"FAREWELL","reg=law,swat|st=friendly,neutral|hour=6,11",{"Let us know if you see anything unusual","Move along, and good luck"}},
{"FAREWELL","reg=law,swat|st=friendly,neutral|hour=19,22",{"Get off the roads, it's nearly dark","Take care, find cover before dark"}},
{"FAREWELL","reg=law,swat|st=friendly,neutral|hour=21,4",{"Go quietly, stay hidden","Be safe, stay low"}},
{"FAREWELL","reg=military,elite|st=friendly,neutral|hour=6,11",{"Move out, stay vigilant","Dismissed, good luck"}},
{"FAREWELL","reg=military,elite|st=friendly,neutral|hour=19,22",{"Dusk is dangerous, move quick and quiet"}},
{"FAREWELL","reg=military,elite|st=friendly,neutral|hour=21,4",{"Out, quiet, don't use lights"}},
{"FAREWELL","reg=outlaw,raider,gang,club,crime,prison|st=friendly,neutral|hour=6,11",{"Later, don't die before breakfast","Go on, scat, I've got a hangover"}},
{"FAREWELL","reg=outlaw,raider,gang,club,crime,prison|st=friendly,neutral|hour=13,18",{"See you, don't steal my stuff, I'll know","Get lost, nicely"}},
{"FAREWELL","reg=outlaw,raider,gang,club,crime,prison|st=friendly,neutral|hour=19,22",{"Beat it, the night's coming and so am I","Don't let the dark catch you, or do, I don't care"}},
{"FAREWELL","reg=outlaw,raider,gang,club,crime,prison|st=friendly,neutral|hour=21,4",{"Get out of here, quietly, I'm trying to sleep","Move along, kid, the night's no place for a talker"}},
{"FAREWELL","tmp=veteran|st=friendly,neutral|hour=21,4",{"Out, quiet"}},
{"FAREWELL","reg=civilian,family|tmp=fresh|st=friendly,neutral|hour=16,5",{"Okay, bye - please be careful, okay? Stay off Main Street after dark"}},
